package cn.zhuatech.bpm;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepWorkflowOpsTests{@Autowired MockMvc mvc;String token;
 @BeforeEach void auth()throws Exception{String j=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin\",\"password\":\"admin123\"}")).andReturn().getResponse().getContentAsString();var m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(j);Assertions.assertTrue(m.find());token=m.group(1);}
 @Test void twoLevelApprovalCompletesInstance()throws Exception{long d=id(admin("/api/admin/workflow-ops/definitions","{\"processKey\":\"PAYMENT-A\",\"versionNo\":1,\"name\":\"付款审批\"}").andReturn());admin("/api/admin/workflow-ops/definitions/"+d+"/nodes","{\"nodeCode\":\"MANAGER\",\"sequenceNo\":1,\"approverRole\":\"MANAGER\",\"slaHours\":4}");admin("/api/admin/workflow-ops/definitions/"+d+"/nodes","{\"nodeCode\":\"FINANCE\",\"sequenceNo\":2,\"approverRole\":\"FINANCE\",\"slaHours\":8}");admin("/api/admin/workflow-ops/definitions/"+d+"/publish","{}");long i=id(call("/api/workflow-ops/instances","{\"instanceNo\":\"PI-A\",\"definitionId\":"+d+",\"initiator\":\"alice\",\"businessKey\":\"PAY-001\"}").andReturn());long t=taskFor(i);call("/api/workflow-ops/tasks/"+t+"/claim","{\"assignee\":\"manager1\"}");call("/api/workflow-ops/tasks/"+t+"/decision","{\"decision\":\"APPROVE\",\"comment\":\"同意\"}");long t2=latestTask();call("/api/workflow-ops/tasks/"+t2+"/claim","{\"assignee\":\"finance1\"}");call("/api/workflow-ops/tasks/"+t2+"/decision","{\"decision\":\"APPROVE\",\"comment\":\"复核通过\"}");mvc.perform(get("/api/workflow-ops/workspace").header("Authorization","Bearer "+token)).andExpect(jsonPath("$.data.instances[0].status").value("COMPLETED"));}
 @Test void definitionWithoutTwoNodesCannotPublish()throws Exception{long d=id(admin("/api/admin/workflow-ops/definitions","{\"processKey\":\"ONE-NODE\",\"versionNo\":1,\"name\":\"错误流程\"}").andReturn());admin("/api/admin/workflow-ops/definitions/"+d+"/nodes","{\"nodeCode\":\"ONLY\",\"sequenceNo\":1,\"approverRole\":\"ADMIN\",\"slaHours\":1}");admin("/api/admin/workflow-ops/definitions/"+d+"/publish","{}").andExpect(status().isConflict());}
 @Test void taskMustBeClaimedBeforeDecision()throws Exception{long d=id(admin("/api/admin/workflow-ops/definitions","{\"processKey\":\"CLAIM-GATE\",\"versionNo\":1,\"name\":\"认领校验\"}").andReturn());for(int n=1;n<=2;n++)admin("/api/admin/workflow-ops/definitions/"+d+"/nodes","{\"nodeCode\":\"N"+n+"\",\"sequenceNo\":"+n+",\"approverRole\":\"ADMIN\",\"slaHours\":1}");admin("/api/admin/workflow-ops/definitions/"+d+"/publish","{}");long i=id(call("/api/workflow-ops/instances","{\"instanceNo\":\"PI-GATE\",\"definitionId\":"+d+",\"initiator\":\"bob\",\"businessKey\":\"BIZ-2\"}").andReturn());call("/api/workflow-ops/tasks/"+taskFor(i)+"/decision","{\"decision\":\"APPROVE\",\"comment\":\"越过认领\"}").andExpect(status().isConflict());}
 ResultActions call(String u,String b)throws Exception{return mvc.perform(post(u).header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return call(u,b);}long id(MvcResult r)throws Exception{return number(r.getResponse().getContentAsString(),"\"id\":(\\d+)");}long taskFor(long i)throws Exception{String j=mvc.perform(get("/api/workflow-ops/workspace").header("Authorization","Bearer "+token)).andReturn().getResponse().getContentAsString();var m=Pattern.compile("\"id\":(\\d+),\"instanceId\":"+i).matcher(j);Assertions.assertTrue(m.find(),j);return Long.parseLong(m.group(1));}long latestTask()throws Exception{String j=mvc.perform(get("/api/workflow-ops/workspace").header("Authorization","Bearer "+token)).andReturn().getResponse().getContentAsString();var m=Pattern.compile("\"tasks\":\\[\\{\"id\":(\\d+)").matcher(j);Assertions.assertTrue(m.find(),j);return Long.parseLong(m.group(1));}long number(String j,String p){var m=Pattern.compile(p).matcher(j);Assertions.assertTrue(m.find(),j);return Long.parseLong(m.group(1));}}
